r = t.add_run('\u300a\u4e2d\u56fd\u5b97\u6559\u53f2\u7eb2\u8981\u300b\u8bfe\u7a0b\u5b66\u4e60\u603b\u7ed3')
r.font.size = Pt(18); r.font.bold = True; r.font.name = '黑体'

t2 = doc.add_paragraph()
t2.alignment = WD_ALIGN_PARAGRAPH.CENTER
r2 = t2.add_run('\u2014\u2014\u4e00\u5b66\u5e74\u8bfe\u7a0b\u5b66\u4e60\u7684\u89c4\u5f8b\u6027\u8ba4\u8bc6\u4e0e\u601d\u8003')
r2.font.size = Pt(14); r2.font.name = '仿宋'

doc.add_paragraph('')

paragraphs = [
# 引言
"\u901a\u8fc7\u4e00\u5b66\u5e74\u300a\u4e2d\u56fd\u5b97\u6559\u53f2\u7eb2\u8981\u300b\u8bfe\u7a0b\u7684\u7cfb\u7edf\u5b66\u4e60\uff0c\u6211\u4ece\u8fdc\u53e4\u65f6\u671f\u7684\u539f\u59cb\u5b97\u6559\u4e00\u76f4\u68b3\u7406\u5230\u65b0\u4e2d\u56fd\u7684\u5b97\u6559\u5de8\u53d8\uff0c\u8de8\u8d8a\u4e86\u6570\u767e\u4e07\u5e74\u7684\u5386\u53f2\u957f\u6cb3\u3002\u8001\u5e08\u4ee5\u5b97\u6559\u4e2d\u56fd\u5316\u4e3a\u4e3b\u7ebf\uff0c\u8d2f\u901a\u5112\u91ca\u9053\u53ca\u5916\u6765\u5b97\u6559\u7684\u53d1\u5c55\u8109\u7edc\uff0c\u5c06\u5b8f\u5927\u7684\u5386\u53f2\u7eb2\u8981\u8bb2\u5f97\u6e05\u6670\u901a\u900f\u3002\u5728\u5b66\u4e60\u8fc7\u7a0b\u4e2d\uff0c\u6211\u9010\u6b65\u53d1\u73b0\u4e86\u4e00\u4e9b\u5177\u6709\u89c4\u5f8b\u6027\u7684\u95ee\u9898\u548c\u8ba4\u8bc6\uff0c\u73b0\u5c06\u8fd9\u4e9b\u601d\u8003\u603b\u7ed3\u5982\u4e0b\u3002",

# 一
"\u4e00\u3001\u5b97\u6559\u4e2d\u56fd\u5316\u662f\u6240\u6709\u5b97\u6559\u5728\u4e2d\u56fd\u751f\u5b58\u53d1\u5c55\u7684\u5fc5\u7531\u4e4b\u8def",

"\u8fd9\u662f\u8bfe\u7a0b\u4e2d\u53cd\u590d\u5f3a\u8c03\u7684\u6700\u6838\u5fc3\u7ebf\u7d22\u3002\u8001\u5e08\u5728\u5f00\u7bc7\u5c31\u660e\u786e\u63d0\u51fa\uff0c\u4eca\u5929\u6211\u4eec\u5b66\u4e60\u4e2d\u56fd\u5b97\u6559\u53f2\uff0c\u8981\u4ee5\u5404\u5b97\u6559\u7684\u6c49\u5316\u3001\u534e\u5316\u3001\u4e2d\u56fd\u5316\u4e3a\u4e3b\u7ebf\uff0c\u91cd\u65b0\u68b3\u7406\u5404\u5b97\u6559\u7684\u4ea7\u751f\u3001\u4f20\u5165\u3001\u53d1\u5c55\u3001\u53d8\u8fc1\u5386\u7a0b\u3002\u901a\u8fc7\u4e00\u5b66\u5e74\u7684\u5b66\u4e60\uff0c\u6211\u6df1\u523b\u4f53\u4f1a\u5230\uff0c\u65e0\u8bba\u662f\u672c\u571f\u4ea7\u751f\u7684\u9053\u6559\uff0c\u8fd8\u662f\u5916\u6765\u7684\u4f5b\u6559\u3001\u4f0a\u65af\u5170\u6559\u3001\u5929\u4e3b\u6559\u548c\u57fa\u7763\u6559\uff0c\u51e1\u662f\u5728\u4e2d\u56fd\u5386\u53f2\u4e0a\u5f97\u4ee5\u5ef6\u7eed\u548c\u53d1\u5c55\u7684\u5b97\u6559\uff0c\u65e0\u4e00\u4f8b\u5916\u90fd\u7ecf\u5386\u4e86\u4e2d\u56fd\u5316\u7684\u8fc7\u7a0b\u3002",

"\u4f5b\u6559\u7684\u4e2d\u56fd\u5316\u6700\u4e3a\u5178\u578b\u3002\u8bfe\u7a0b\u4ece\u6c49\u4ee3\u4f5b\u6559\u4f20\u5165\u65f6\u4f5b\u9640\u4f9d\u9644\u4e8e\u9ec4\u8001\u5d07\u62dc\u8bb2\u8d77\uff0c\u5230\u9b4f\u664b\u5357\u5317\u671d\u65f6\u671f\u4e0e\u7384\u5b66\u878d\u5408\uff0c\u518d\u5230\u968b\u5510\u65f6\u671f\u5f62\u6210\u5929\u53f0\u5b97\u3001\u7985\u5b97\u3001\u534e\u4e25\u5b97\u7b49\u516b\u4e2a\u4e2d\u56fd\u5316\u5b97\u6d3e\uff0c\u6e05\u6670\u5730\u5c55\u73b0\u4e86\u4f5b\u6559\u4e2d\u56fd\u5316\u7684\u5b8c\u6574\u8109\u7edc\u3002\u5c24\u5176\u662f\u7985\u5b97\uff0c\u4ee5\u6559\u5916\u522b\u4f20\u3001\u4e0d\u7acb\u6587\u5b57\u3001\u4ee5\u5fc3\u4f20\u5fc3\u3001\u660e\u5fc3\u89c1\u6027\u7684\u7406\u5ff5\uff0c\u5927\u80c6\u9769\u65b0\u5370\u5ea6\u4f5b\u6559\u7ecf\u5178\u675f\u7f1a\uff0c\u6210\u4e3a\u4f5b\u6559\u4e2d\u56fd\u5316\u6700\u5f7b\u5e95\u7684\u6210\u679c\u3002\u8001\u5e08\u8fd8\u7279\u522b\u8bb2\u5230\u6881\u6b66\u5e1d\u4e0e\u8fbe\u6469\u90ed\u7136\u65e0\u5723\u7684\u516c\u6848\uff0c\u8ba9\u6211\u4eec\u770b\u5230\u4e2d\u56fd\u5316\u7684\u7985\u5b97\u5bf9\u529f\u5229\u6027\u4fe1\u4ef0\u7684\u8d85\u8d8a\u3002\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u90a3\u4e9b\u672a\u80fd\u5b8c\u6210\u4e2d\u56fd\u5316\u7684\u5b97\u6559\uff0c\u5982\u5510\u4ee3\u7684\u666f\u6559\u3001\u795a\u6559\u3001\u6469\u5c3c\u6559\u7b49\u897f\u6765\u5b97\u6559\uff0c\u6700\u7ec8\u90fd\u672a\u80fd\u5728\u4e2d\u56fd\u624e\u6839\u3002",

"\u4f0a\u65af\u5170\u6559\u7684\u4e2d\u56fd\u5316\u4e5f\u4ee4\u4eba\u5370\u8c61\u6df1\u523b\u3002\u8001\u5e08\u8bb2\u5230\u660e\u4ee3\u7a46\u65af\u6797\u5b66\u8005\u5f00\u5c55\u4ee5\u5112\u91ca\u56de\u7684\u5b97\u6559\u672c\u571f\u5316\u8fd0\u52a8\uff0c\u521b\u7acb\u7ecf\u5802\u6559\u80b2\uff0c\u5f62\u6210\u4e86\u72ec\u7279\u7684\u7a46\u65af\u6797\u4fe1\u4ef0\u548c\u751f\u6d3b\u6a21\u5f0f\u3002\u5929\u4e3b\u6559\u5728\u660e\u672b\u7531\u5229\u739b\u7aa6\u7b49\u897f\u5112\u5f00\u6559\uff0c\u91c7\u53d6\u4e86\u9002\u5e94\u4e2d\u56fd\u6587\u5316\u7684\u4f20\u6559\u7b56\u7565\uff0c\u5f00\u6559\u4e09\u5927\u67f1\u77f3\u66f4\u662f\u5c06\u5929\u4e3b\u6559\u4e49\u4e0e\u4e2d\u56fd\u4f20\u7edf\u601d\u60f3\u76f8\u7ed3\u5408\u3002\u8fd9\u4e9b\u5386\u53f2\u4e8b\u5b9e\u5145\u5206\u8bf4\u660e\uff0c\u5b97\u6559\u4e2d\u56fd\u5316\u4e0d\u662f\u53ef\u6709\u53ef\u65e0\u7684\u9009\u62e9\uff0c\u800c\u662f\u5b97\u6559\u5728\u4e2d\u56fd\u751f\u5b58\u53d1\u5c55\u7684\u5fc5\u7136\u89c4\u5f8b\u3002",

# 二
"\u4e8c\u3001\u653f\u6559\u5173\u7cfb\u7684\u4e1c\u65b9\u6a21\u5f0f\u51b3\u5b9a\u4e86\u4e2d\u56fd\u5b97\u6559\u7684\u57fa\u672c\u683c\u5c40",

"\u8bfe\u7a0b\u6df1\u523b\u63ed\u793a\u4e86\u4e2d\u56fd\u653f\u6559\u5173\u7cfb\u7684\u72ec\u7279\u6027\u3002\u4e0e\u897f\u65b9\u793e\u4f1a\u6559\u6743\u9ad8\u4e8e\u7687\u6743\u751a\u81f3\u6559\u6743\u4e0e\u7687\u6743\u5e76\u7acb\u7684\u5c40\u9762\u5b8c\u5168\u4e0d\u540c\uff0c\u4e2d\u56fd\u81ea\u53e4\u4ee5\u6765\u5c31\u662f\u541b\u9053\u81f3\u5c0a\u3001\u7687\u6743\u81f3\u4e0a\uff0c\u4e00\u5207\u5b97\u6559\u7ec4\u7ec7\u90fd\u5fc5\u987b\u4f9d\u9644\u4e8e\u7687\u6743\uff0c\u7edd\u4e0d\u5141\u8bb8\u51fa\u73b0\u6559\u6743\u9ad8\u4e8e\u7687\u6743\u7684\u5c40\u9762\uff0c\u65e0\u6cd5\u4ea7\u751f\u56fd\u6559\u3002",

"\u4e1c\u664b\u9053\u5b89\u6cd5\u5e08\u63d0\u51fa\u7684\u4e0d\u4f9d\u56fd\u4e3b\u5219\u6cd5\u4e8b\u96be\u7acb\uff0c\u6210\u4e3a\u5386\u4ee3\u653f\u6559\u5173\u7cfb\u7684\u51c6\u5219\uff0c\u8fd9\u4e00\u8bba\u65ad\u5728\u4e4b\u540e\u8fd1\u4e24\u5343\u5e74\u7684\u5386\u53f2\u4e2d\u53cd\u590d\u5f97\u5230\u9a8c\u8bc1\u3002\u4ece\u590f\u5546\u5468\u7684\u7edd\u5730\u5929\u901a\u6539\u9769\u5f00\u59cb\uff0c\u5b97\u6559\u6743\u529b\u5c31\u88ab\u6536\u5f52\u4e8e\u56fd\u541b\u624b\u4e2d\uff0c\u653f\u6cbb\u51cc\u9a7e\u4e8e\u5b97\u6559\u4e4b\u4e0a\uff0c\u5b97\u6559\u5fc5\u987b\u670d\u4ece\u653f\u6cbb\u3002\u79e6\u6c49\u65f6\u671f\uff0c\u5112\u6559\u88ab\u7ecf\u5178\u5316\u3001\u5236\u5ea6\u5316\uff0c\u6210\u4e3a\u5b98\u65b9\u610f\u8bc6\u5f62\u6001\u3002\u968b\u5510\u65f6\u671f\uff0c\u671d\u5ef7\u5b9e\u884c\u4e09\u6559\u5e76\u7528\u653f\u7b56\u548c\u53cc\u8f68\u5236\u7684\u5b97\u6559\u7ba1\u7406\u673a\u6784\uff0c\u8868\u9762\u4e0a\u50e7\u5b98\u3001\u9053\u5b98\u81ea\u6cbb\uff0c\u5b9e\u9645\u4e0a\u653f\u5e9c\u5b98\u5458\u4efb\u804c\u7684\u4fd7\u5b98\u4f53\u7cfb\u7262\u7262\u5730\u63a7\u5236\u4f4f\u4e86\u5b97\u6559\u53d1\u5c55\u7684\u547d\u8109\u3002\u5510\u6b66\u5b97\u706d\u4f5b\u3001\u540e\u5468\u4e16\u5b97\u706d\u4f5b\u7b49\u4e8b\u4ef6\uff0c\u66f4\u662f\u7687\u6743\u53ef\u4ee5\u968f\u65f6\u5e72\u9884\u751a\u81f3\u6253\u538b\u5b97\u6559\u7684\u76f4\u63a5\u8bc1\u660e\u3002",

"\u901a\u8fc7\u8bfe\u7a0b\u5b66\u4e60\u6211\u8ba4\u8bc6\u5230\uff0c\u8fd9\u79cd\u4e1c\u65b9\u6a21\u5f0f\u7684\u653f\u6559\u5173\u7cfb\u6709\u5176\u6df1\u523b\u7684\u793e\u4f1a\u6839\u6e90\u3002\u4e2d\u56fd\u662f\u5178\u578b\u7684\u519c\u4e1a\u793e\u4f1a\uff0c\u6ce8\u91cd\u73b0\u5b9e\u6027\u548c\u529f\u5229\u6027\uff0c\u4fe1\u9b3c\u795e\u4f46\u66f4\u754f\u60e7\u6743\u52bf\u3002\u5728\u8fd9\u6837\u7684\u6587\u5316\u571f\u58e4\u4e2d\uff0c\u5b97\u6559\u53ea\u80fd\u4ee5\u62a4\u56fd\u4f51\u6c11\u4e3a\u65d7\u5e1c\u5bfb\u6c42\u751f\u5b58\u7a7a\u95f4\uff0c\u800c\u4e0d\u80fd\u51cc\u9a7e\u4e8e\u653f\u6cbb\u4e4b\u4e0a\u3002\u8fd9\u4e5f\u662f\u4e3a\u4ec0\u4e48\u4e2d\u56fd\u5386\u53f2\u4e0a\u867d\u7136\u5b97\u6559\u7e41\u591a\uff0c\u4f46\u4ece\u672a\u51fa\u73b0\u8fc7\u50cf\u6b27\u6d32\u4e2d\u4e16\u7eaa\u90a3\u6837\u4e00\u6559\u72ec\u5927\u7684\u653f\u6559\u5408\u4e00\u5c40\u9762\u3002",

# 三
"\u4e09\u3001\u4e09\u6559\u5173\u7cfb\u4ece\u51b2\u7a81\u8d70\u5411\u878d\u5408\u662f\u4e0d\u53ef\u9006\u8f6c\u7684\u5386\u53f2\u8d8b\u52bf",

"\u8bfe\u7a0b\u7528\u4e86\u5927\u91cf\u7bc7\u5e45\u8bb2\u8ff0\u5112\u91ca\u9053\u4e09\u6559\u7684\u5173\u7cfb\u6f14\u53d8\uff0c\u5448\u73b0\u51fa\u4e00\u6761\u6e05\u6670\u7684\u89c4\u5f8b\uff1a\u4ece\u51b2\u7a81\u5230\u878d\u5408\uff0c\u6700\u7ec8\u5f62\u6210\u4e09\u6559\u5408\u4e00\u7684\u5171\u8bc6\u3002",

"\u79e6\u6c49\u65f6\u671f\uff0c\u5112\u6559\u786e\u7acb\u3001\u4f5b\u6559\u4f20\u5165\u3001\u9053\u6559\u521b\u7acb\uff0c\u4e09\u6559\u5f00\u59cb\u4e92\u76f8\u4e86\u89e3\u548c\u501f\u9274\uff0c\u4f46\u4e5f\u5b58\u5728\u77db\u76fe\u548c\u51b2\u7a81\uff0c\u5bfc\u81f4\u5317\u9b4f\u3001\u5317\u5468\u6b66\u5e1d\u4e24\u6b21\u706d\u4f5b\u3002\u9b4f\u664b\u5357\u5317\u671d\u65f6\u671f\uff0c\u4e09\u6559\u5728\u78b0\u649e\u4e2d\u4ea4\u6d41\u53d1\u5c55\uff0c\u9b4f\u664b\u7384\u5b66\u6210\u4e3a\u5112\u9053\u878d\u5408\u7684\u91cd\u8981\u6865\u6881\u3002\u968b\u5510\u65f6\u671f\uff0c\u4e09\u6559\u5904\u4e8e\u9f0e\u76db\u9636\u6bb5\uff0c\u4f46\u51b2\u7a81\u4ecd\u7136\u5b58\u5728\uff0c\u5510\u6b66\u5b97\u706d\u4f5b\u548c\u540e\u5468\u4e16\u5b97\u6cd5\u96be\u5c31\u662f\u660e\u8bc1\u3002\u8bfe\u7a0b\u4e2d\u7279\u522b\u63d0\u5230\u5b8b\u5fbd\u5b97\u5d07\u9053\u6392\u4f5b\u4e8b\u4ef6\uff0c\u8ba9\u6211\u4eec\u770b\u5230\u4e09\u6559\u4e4b\u4e89\u5728\u4e2d\u53e4\u65f6\u4ee3\u89c4\u6a21\u5b8f\u5927\u3002",

"\u7136\u800c\u5230\u4e86\u5b8b\u4ee3\uff0c\u60c5\u51b5\u53d1\u751f\u4e86\u6839\u672c\u8f6c\u53d8\u3002\u8001\u5e08\u8bb2\u5230\uff0c\u5b8b\u4ee3\u4e09\u6559\u5408\u4e00\u6210\u4e3a\u793e\u4f1a\u6f6e\u6d41\u3002\u5112\u5bb6\u7684\u7406\u5b66\u3001\u6c14\u5b66\u3001\u5fc3\u5b66\u878d\u6c47\u4f5b\u6559\u601d\u60f3\uff0c\u5929\u53f0\u5b97\u3001\u7985\u5b97\u7b49\u4e2d\u56fd\u5316\u4f5b\u5b66\u5b8c\u6210\uff0c\u9053\u6559\u5185\u4e39\u5b66\u5174\u8d77\uff0c\u4e09\u6559\u8d8b\u540c\u660e\u663e\u3002\u660e\u4ee3\u738b\u9633\u660e\u7684\u5fc3\u5b66\u3001\u4f5b\u6559\u7985\u5b66\u548c\u9053\u6559\u5185\u4e39\u5b66\u5357\u5317\u4e8c\u5b97\u5728\u5fc3\u7684\u89e3\u8bfb\u4e0a\u5b8c\u6210\u5168\u65b0\u7684\u7edf\u4e00\uff0c\u4e09\u6559\u878d\u5408\u5f62\u6210\u5171\u8bc6\uff0c\u6b64\u540e\u4e0d\u518d\u51fa\u73b0\u4e09\u6559\u51b2\u7a81\u4e8b\u4ef6\u3002",

"\u8fd9\u4e00\u89c4\u5f8b\u7ed9\u6211\u5f88\u5927\u7684\u542f\u53d1\u3002\u4e09\u6559\u4e4b\u6240\u4ee5\u80fd\u591f\u4ece\u51b2\u7a81\u8d70\u5411\u878d\u5408\uff0c\u6839\u672c\u539f\u56e0\u5728\u4e8e\u5b83\u4eec\u90fd\u6839\u690d\u4e8e\u4e2d\u534e\u6587\u5316\u7684\u571f\u58e4\uff0c\u5171\u4eab\u7740\u76f8\u540c\u7684\u4ef7\u503c\u57fa\u7840\uff0c\u5112\u5bb6\u7684\u4f26\u7406\u9053\u5fb7\u3001\u9053\u5bb6\u7684\u81ea\u7136\u65e0\u4e3a\u3001\u4f5b\u5bb6\u7684\u6148\u60b2\u667a\u6167\uff0c\u6700\u7ec8\u90fd\u6307\u5411\u4eba\u7684\u7cbe\u795e\u5b89\u987f\u548c\u793e\u4f1a\u7684\u548c\u8c10\u7a33\u5b9a\u3002\u4e2d\u534e\u6587\u5316\u5177\u6709\u591a\u5143\u4e00\u4f53\u3001\u548c\u800c\u4e0d\u540c\u3001\u517c\u6536\u5e76\u84c4\u3001\u6b8a\u9014\u540c\u5f52\u7684\u5305\u5bb9\u7cbe\u795e\uff0c\u8fd9\u6b63\u662f\u4e09\u6559\u80fd\u591f\u8d70\u5411\u878d\u5408\u7684\u6df1\u5c42\u6587\u5316\u57fa\u7840\u3002",

# 四
"\u56db\u3001\u539f\u751f\u578b\u5b97\u6cd5\u5b97\u6559\u7684\u4e00\u8d2f\u5b58\u7eed\u662f\u4e2d\u56fd\u5b97\u6559\u7684\u72ec\u7279\u73b0\u8c61",

"\u8bfe\u7a0b\u4e2d\u63d0\u51fa\u4e86\u4e00\u4e2a\u975e\u5e38\u6df1\u523b\u7684\u89c2\u70b9\uff1a\u5b97\u6cd5\u6027\u5b97\u6559\u662f\u4e2d\u56fd\u7684\u539f\u751f\u578b\u5b97\u6559\uff0c\u5728\u53e4\u4ee3\u793e\u4f1a\u8fde\u7eed\u5b58\u5728\u548c\u53d1\u5c55\uff0c\u4e00\u76f4\u5ef6\u7eed\u5230\u8fd1\u73b0\u4ee3\u793e\u4f1a\uff0c\u8fd9\u5728\u4e16\u754c\u5404\u5927\u6587\u660e\u4e2d\u662f\u72ec\u4e00\u65e0\u4e8c\u7684\u3002",

"\u6309\u7167\u5b97\u6559\u53d1\u5c55\u7684\u4e00\u822c\u89c4\u5f8b\uff0c\u8bb8\u591a\u6c11\u65cf\u7684\u539f\u59cb\u5b97\u6559\u5728\u56fd\u5bb6\u4ea7\u751f\u540e\u9010\u6e10\u6d88\u4ea1\uff0c\u4e3a\u53e4\u4ee3\u56fd\u5bb6\u521b\u751f\u578b\u5b97\u6559\u6240\u53d6\u4ee3\u3002\u4f46\u4e2d\u56fd\u8d70\u4e86\u72ec\u7279\u7684\u8def\u5f84\uff0c\u590f\u5546\u5468\u4e09\u4ee3\u5f3a\u5316\u4e86\u6c0f\u65cf\u8840\u7f18\u5173\u7cfb\uff0c\u5efa\u6210\u4ee5\u7537\u6027\u8840\u7f18\u548c\u7956\u5b97\u5d07\u62dc\u4e3a\u7ebd\u5e26\u7684\u5b97\u6cd5\u6027\u5b97\u6559\uff0c\u8fd9\u79cd\u5b97\u6559\u5728\u53e4\u4ee3\u793e\u4f1a\u8fde\u7eed\u5b58\u5728\u548c\u53d1\u5c55\uff0c\u5206\u5316\u5206\u5c42\u4ee5\u9002\u5e94\u5404\u79cd\u9700\u6c42\uff0c\u5e76\u4e14\u4e0e\u5c01\u5efa\u4f53\u5236\u7ecf\u8fc7\u6574\u5408\uff0c\u4e92\u76f8\u652f\u6491\u3002",

"\u8bfe\u7a0b\u8be6\u7ec6\u5206\u6790\u4e86\u5b97\u6cd5\u6027\u5b97\u6559\u7684\u6838\u5fc3\u5185\u5bb9\uff0c\u5373\u656c\u5929\u3001\u796d\u7956\u3001\u7940\u9b3c\u795e\uff0c\u4ee5\u53ca\u7531\u6b64\u884d\u751f\u51fa\u7684\u7edd\u5730\u5929\u901a\u3001\u795e\u9053\u8bbe\u6559\u3001\u656c\u9b3c\u795e\u800c\u8fdc\u4e4b\u3001\u5937\u590f\u4e4b\u8fa8\u7b49\u91cd\u8981\u7406\u8bba\u548c\u89c2\u70b9\u3002\u8fd9\u4e9b\u601d\u60f3\u6df1\u523b\u5f71\u54cd\u4e86\u6b64\u540e\u4e24\u5343\u591a\u5e74\u7684\u4e2d\u56fd\u5b97\u6559\u683c\u5c40\u3002\u7279\u522b\u662f\u795e\u9053\u8bbe\u6559\u7406\u8bba\uff0c\u5f3a\u8c03\u7528\u4f20\u7edf\u5b97\u6559\u7684\u529b\u91cf\u8fbe\u5230\u63a8\u884c\u6559\u5316\u3001\u6587\u9970\u653f\u4e8b\u3001\u7ef4\u62a4\u5b97\u6cd5\u7b49\u7ea7\u79e9\u5e8f\u7684\u76ee\u7684\uff0c\u4f7f\u5f97\u4e2d\u56fd\u5b97\u6559\u59cb\u7ec8\u4e0e\u4f26\u7406\u6559\u5316\u7d27\u5bc6\u7ed3\u5408\uff0c\u800c\u672a\u80fd\u53d1\u5c55\u4e3a\u72ec\u7acb\u7684\u795e\u6743\u4f53\u7cfb\u3002",

"\u8fd9\u4e00\u89c4\u5f8b\u8ba9\u6211\u8ba4\u8bc6\u5230\uff0c\u7406\u89e3\u4e2d\u56fd\u5b97\u6559\u5fc5\u987b\u4ece\u8fd9\u4e2a\u539f\u751f\u578b\u7684\u5b97\u6cd5\u5b97\u6559\u51fa\u53d1\u3002\u4f5b\u6559\u4e4b\u6240\u4ee5\u80fd\u5728\u4e2d\u56fd\u624e\u6839\uff0c\u5f88\u5927\u7a0b\u5ea6\u4e0a\u662f\u56e0\u4e3a\u5b83\u5438\u6536\u4e86\u4e2d\u56fd\u4f20\u7edf\u7684\u7956\u5148\u5d07\u62dc\u548c\u5b5d\u9053\u89c2\u5ff5\u3002\u9053\u6559\u4e4b\u6240\u4ee5\u80fd\u6210\u4e3a\u4e2d\u56fd\u552f\u4e00\u7684\u672c\u571f\u5236\u5ea6\u6027\u5b97\u6559\uff0c\u4e5f\u662f\u56e0\u4e3a\u5b83\u7ee7\u627f\u4e86\u9053\u5bb6\u548c\u9ec4\u8001\u4e4b\u5b66\u7684\u601d\u60f3\u8d44\u6e90\uff0c\u5e76\u4e0e\u5b97\u6cd5\u6027\u5b97\u6559\u7684\u796d\u7940\u4f20\u7edf\u76f8\u7ed3\u5408\u3002",

# 五
"\u4e94\u3001\u5b97\u6559\u7684\u5174\u8870\u4e0e\u793e\u4f1a\u7ecf\u6d4e\u8363\u8fb1\u4e0e\u5171\u3001\u4e00\u8109\u76f8\u8fde",

"\u8001\u5e08\u5728\u8bb2\u8ff0\u968b\u5510\u4e94\u4ee3\u5b97\u6559\u65f6\u63d0\u51fa\u4e86\u4e00\u4e2a\u91cd\u8981\u7684\u5224\u65ad\uff1a\u5b97\u6559\u7684\u53d1\u5c55\u3001\u5174\u76db\u548c\u8870\u843d\u7684\u547d\u8fd0\uff0c\u662f\u540c\u4e2d\u56fd\u793e\u4f1a\u7684\u7ecf\u6d4e\u8363\u8fb1\u4e0e\u5171\u3001\u4e00\u8109\u76f8\u8fde\u7684\u3002",

"\u968b\u5510\u65f6\u671f\u56fd\u5bb6\u7edf\u4e00\u3001\u7ecf\u6d4e\u7e41\u8363\u3001\u7586\u57df\u62d3\u5c55\u3001\u5bf9\u5916\u4ea4\u6d41\u9891\u7e41\uff0c\u5b97\u6559\u4e5f\u8fbe\u5230\u4e86\u7a7a\u524d\u7684\u5174\u76db\u3002\u4f5b\u6559\u5f62\u6210\u4e86\u516b\u5927\u5b97\u6d3e\uff0c\u9053\u6559\u5728\u674e\u5510\u738b\u671d\u7684\u63a8\u5d07\u4e0b\u76db\u6781\u4e00\u65f6\uff0c\u4f0a\u65af\u5170\u6559\u3001\u666f\u6559\u3001\u795a\u6559\u3001\u6469\u5c3c\u6559\u7b49\u5916\u6765\u5b97\u6559\u7eb7\u7eb7\u4f20\u5165\u3002\u8bfe\u7a0b\u4e2d\u5f15\u7528\u675c\u752b\u7684\u8bd7\u53e5\u5fc6\u6614\u5f00\u5143\u5168\u76db\u65e5\uff0c\u5c0f\u9091\u72b9\u85cf\u4e07\u5bb6\u5ba4\uff0c\u7a3b\u7c73\u6d41\u8102\u7c9f\u7c73\u767d\uff0c\u516c\u79c1\u4ed3\u5ec9\u4ff1\u4e30\u5b9e\uff0c\u6b63\u662f\u8fd9\u79cd\u76db\u4e16\u6c14\u8c61\u5b55\u80b2\u4e86\u5b97\u6559\u7684\u7e41\u8363\u3002",

"\u7136\u800c\u4e2d\u5510\u4e4b\u540e\uff0c\u4e2d\u56fd\u793e\u4f1a\u4ece\u9876\u5cf0\u5f00\u59cb\u8d70\u4e0b\u5761\u8def\uff0c\u5b97\u6559\u4e5f\u7531\u6b64\u800c\u6bcf\u51b5\u6108\u4e0b\u3002\u5510\u6b66\u5b97\u706d\u4f5b\u867d\u6709\u653f\u6cbb\u548c\u7ecf\u6d4e\u539f\u56e0\uff0c\u4f46\u4e5f\u53cd\u6620\u4e86\u56fd\u5bb6\u8870\u843d\u65f6\u671f\u5b97\u6559\u4e0e\u4fd7\u4e16\u529b\u91cf\u4e4b\u95f4\u7684\u77db\u76fe\u6fc0\u5316\u3002\u5230\u4e86\u660e\u6e05\u65f6\u671f\uff0c\u9053\u6559\u6e10\u8d8b\u8870\u843d\uff0c\u4f5b\u6559\u4e5f\u5728\u8870\u5fae\u4e2d\u8d77\u4f0f\uff0c\u8fd9\u79cd\u8d8b\u52bf\u4e0e\u56fd\u5bb6\u6574\u4f53\u7684\u8870\u843d\u662f\u4e00\u81f4\u7684\u3002",

"\u6c11\u56fd\u65f6\u671f\u548c\u65b0\u4e2d\u56fd\u65f6\u671f\u7684\u5185\u5bb9\u8fdb\u4e00\u6b65\u5370\u8bc1\u4e86\u8fd9\u4e00\u89c4\u5f8b\u3002\u6c11\u56fd\u65f6\u671f\u6218\u4e71\u4e0d\u65ad\u3001\u6c11\u4e0d\u804a\u751f\uff0c\u5404\u5b97\u6559\u90fd\u5728\u51b2\u51fb\u4e2d\u5bfb\u6c42\u8f6c\u578b\u3002\u65b0\u4e2d\u56fd\u6210\u7acb\u540e\uff0c\u7279\u522b\u662f\u6539\u9769\u5f00\u653e\u4ee5\u6765\uff0c\u5b97\u6559\u4e8b\u4e1a\u83b7\u5f97\u4e86\u65b0\u7684\u53d1\u5c55\u7a7a\u95f4\u3002\u65b0\u65f6\u4ee3\u5b97\u6559\u5de5\u4f5c\u5f3a\u8c03\u5b97\u6559\u4e2d\u56fd\u5316\u548c\u4ece\u4e25\u6cbb\u6559\uff0c\u5404\u5b97\u6559\u4e0e\u793e\u4f1a\u76f8\u9002\u5e94\uff0c\u5448\u73b0\u51fa\u5168\u65b0\u7684\u9762\u8c8c\u3002",

# 六
"\u516d\u3001\u4e2d\u56fd\u5b97\u6559\u5448\u73b0\u663e\u9690\u4e8c\u6027\u548c\u4e09\u91cd\u7ed3\u6784\u7684\u72ec\u7279\u5f62\u6001",

"\u8bfe\u7a0b\u4e2d\u63d0\u51fa\u4e86\u4e00\u4e2a\u6781\u5177\u89e3\u91ca\u529b\u7684\u5206\u6790\u6846\u67b6\uff1a\u4e2d\u56fd\u5b97\u6559\u5448\u73b0\u663e\u9690\u4e8c\u6027\uff0c\u663e\u6027\u5b97\u6559\u5373\u5236\u5ea6\u6027\u5b97\u6559\uff0c\u4e3a\u4fe1\u4ef0\u7684\u4e3b\u6d41\uff0c\u9690\u6027\u5b97\u6559\u5373\u5206\u6563\u6027\u5b97\u6559\uff0c\u4e3a\u4fe1\u4ef0\u7684\u6f5c\u6d41\u3002\u540c\u65f6\uff0c\u56e0\u4fe1\u4ef0\u8005\u8eab\u4efd\u7684\u4e0d\u540c\uff0c\u5404\u5b97\u6559\u5185\u90e8\u4e5f\u5f62\u6210\u4e09\u91cd\u7ed3\u6784\uff0c\u5b98\u65b9\u4fe1\u4ef0\u5f3a\u8c03\u541b\u6743\u795e\u6388\u548c\u4f26\u7406\u6559\u5316\uff0c\u58eb\u5927\u592b\u548c\u5b66\u8005\u628a\u4fe1\u4ef0\u4f5c\u4e3a\u5b89\u8eab\u7acb\u547d\u7684\u624b\u6bb5\uff0c\u5021\u5bfc\u5112\u5bb6\u6cbb\u56fd\u3001\u9053\u5bb6\u6cbb\u8eab\u3001\u4f5b\u5bb6\u6cbb\u5fc3\uff0c\u6c11\u95f4\u7684\u4fe1\u4ef0\u5219\u591a\u6837\u3001\u5e9e\u6742\u3001\u6613\u53d8\u3001\u5b9e\u7528\u3002",

"\u8fd9\u4e00\u89c4\u5f8b\u5728\u8bfe\u7a0b\u7684\u5404\u4e2a\u9636\u6bb5\u4e2d\u53cd\u590d\u5f97\u5230\u5370\u8bc1\u3002\u5b98\u65b9\u5c42\u9762\uff0c\u4ece\u590f\u5546\u5468\u7684\u5b97\u5e99\u796d\u7940\u5236\u5ea6\u5230\u968b\u5510\u7684\u5b97\u6559\u7ba1\u7406\u673a\u6784\uff0c\u518d\u5230\u660e\u6e05\u7684\u50e7\u5b98\u5236\u5ea6\uff0c\u5b97\u6559\u59cb\u7ec8\u88ab\u7eb3\u5165\u56fd\u5bb6\u6cbb\u7406\u4f53\u7cfb\u4e4b\u4e2d\u3002\u58eb\u5927\u592b\u5c42\u9762\uff0c\u9b4f\u664b\u7384\u5b66\u5bb6\u4ee5\u8001\u5e84\u601d\u60f3\u89e3\u8bfb\u5112\u5bb6\u7ecf\u5178\uff0c\u5b8b\u660e\u7406\u5b66\u5bb6\u878d\u6c47\u4f5b\u9053\u601d\u60f3\u6784\u5efa\u65b0\u5112\u5b66\uff0c\u6c11\u56fd\u65f6\u671f\u8d75\u7d2b\u741b\u3001\u5434\u96f7\u5ddd\u3001\u8c22\u6276\u96c5\u7b49\u795e\u5b66\u5bb6\u5c06\u57fa\u7763\u6559\u4e0e\u4e2d\u56fd\u6587\u5316\u5bf9\u63a5\uff0c\u90fd\u4f53\u73b0\u4e86\u77e5\u8bc6\u7cbe\u82f1\u5c06\u4fe1\u4ef0\u4e0e\u5b66\u672f\u76f8\u7ed3\u5408\u7684\u7279\u70b9\u3002\u6c11\u95f4\u5c42\u9762\uff0c\u8bfe\u7a0b\u4e2d\u5927\u91cf\u63cf\u8ff0\u4e86\u5404\u79cd\u6c11\u95f4\u4fe1\u4ef0\u3001\u6c11\u95f4\u5b97\u6559\u7684\u5174\u8870\u53d8\u5316\uff0c\u4ece\u767d\u83b2\u6559\u5230\u5404\u79cd\u5730\u65b9\u795e\u7075\u5d07\u62dc\uff0c\u5c55\u73b0\u4e86\u6c11\u95f4\u4fe1\u4ef0\u7684\u591a\u6837\u6027\u548c\u5b9e\u7528\u6027\u7279\u5f81\u3002",

# 七
"\u4e03\u3001\u96c5\u4fd7\u4e92\u52a8\u662f\u4e2d\u56fd\u5b97\u6559\u6587\u5316\u53d1\u5c55\u7684\u91cd\u8981\u52a8\u529b",

"\u8bfe\u7a0b\u5728\u8bb2\u8ff0\u793c\u5931\u800c\u6c42\u8bf8\u91ce\u65f6\u63d0\u51fa\u4e86\u4e00\u4e2a\u6df1\u523b\u7684\u89c1\u89e3\uff1a\u96c5\u4e0e\u4fd7\u7684\u4e92\u52a8\u662f\u4e2d\u56fd\u6587\u5316\u53d1\u5c55\u4e0e\u6574\u5408\u4e92\u52a8\u7684\u673a\u5236\uff0c\u53c8\u662f\u5236\u5ea6\u6027\u5b97\u6559\u4e0e\u6c11\u95f4\u4fe1\u4ef0\u7684\u4ea4\u4e92\u53d1\u5c55\u673a\u5236\u3002",

"\u9053\u6559\u7684\u53d1\u5c55\u5386\u7a0b\u662f\u8fd9\u4e00\u89c4\u5f8b\u7684\u6700\u4f73\u4f8b\u8bc1\u3002\u9053\u6559\u5728\u6c49\u672b\u8d77\u6e90\u4e8e\u6c11\u95f4\uff0c\u5230\u4e86\u4e1c\u664b\u3001\u5357\u671d\u5f97\u5230\u4e0d\u5c11\u4e16\u65cf\u7684\u4fe1\u5949\uff0c\u5730\u4f4d\u9010\u6e10\u63d0\u5347\uff0c\u5230\u4e86\u5510\u671d\u7687\u5e1d\u5927\u529b\u63d0\u5021\uff0c\u4f7f\u4e4b\u5177\u6709\u4e0e\u5112\u5bb6\u548c\u4f5b\u6559\u7b49\u540c\u7684\u5730\u4f4d\uff0c\u8fd9\u662f\u4e00\u4e2a\u5178\u578b\u7684\u7531\u4fd7\u5316\u96c5\u7684\u8fc7\u7a0b\u3002\u53cd\u8fc7\u6765\uff0c\u5112\u5bb6\u601d\u60f3\u4ece\u5b54\u5b50\u6536\u5f92\u8bb2\u5b66\u7684\u79c1\u5b66\uff0c\u5230\u6c49\u6b66\u5e1d\u7f62\u9edc\u767e\u5bb6\u72ec\u5c0a\u5112\u672f\u83b7\u5f97\u5b98\u65b9\u6743\u5a01\u5730\u4f4d\uff0c\u518d\u4e0d\u65ad\u5411\u6c11\u95f4\u666e\u53ca\uff0c\u4e09\u7eb2\u4e94\u5e38\u3001\u5fe0\u5b5d\u8282\u4e49\u7b49\u7b49\u601d\u60f3\u5728\u4eba\u6c11\u751f\u6d3b\u4e2d\u8d77\u7740\u91cd\u8981\u7684\u4f5c\u7528\uff0c\u5e76\u8d2f\u7a7f\u5728\u6c11\u95f4\u4e60\u4fd7\u3001\u4e61\u7ea6\u3001\u5bb6\u89c4\u4ee5\u53ca\u5927\u91cf\u7684\u620f\u66f2\u3001\u5c0f\u8bf4\u4f5c\u54c1\u4e4b\u4e2d\uff0c\u8fd9\u53c8\u662f\u4e00\u4e2a\u7531\u96c5\u5230\u4fd7\u7684\u8fc7\u7a0b\u3002",

"\u8001\u5e08\u6307\u51fa\uff0c\u6bcf\u4e00\u6b21\u7684\u96c5\u5316\u6216\u4fd7\u5316\u90fd\u53ef\u4ee5\u89c6\u4e3a\u6587\u660e\u7684\u4e00\u6b21\u6f14\u8fdb\uff0c\u96c5\u4e0e\u4fd7\u7684\u4e92\u52a8\u4fc3\u8fdb\u4e86\u4e2d\u534e\u6587\u660e\u7684\u53d1\u5c55\u3002\u8fd9\u4e00\u89c4\u5f8b\u4f7f\u6211\u8ba4\u8bc6\u5230\uff0c\u4e2d\u56fd\u5b97\u6559\u6587\u5316\u7684\u751f\u547d\u529b\u6070\u6070\u5728\u4e8e\u5b83\u4e0d\u662f\u4e00\u4e2a\u5c01\u95ed\u7684\u4f53\u7cfb\uff0c\u800c\u662f\u4e00\u4e2a\u5f00\u653e\u7684\u3001\u4e0d\u65ad\u4ece\u6c11\u95f4\u6c72\u53d6\u8425\u517b\u3001\u53c8\u4e0d\u65ad\u5411\u6c11\u95f4\u4f20\u64ad\u6559\u5316\u7684\u52a8\u6001\u8fc7\u7a0b\u3002",

# 结语
"\u7ed3\u8bed",

"\u901a\u8fc7\u4e00\u5b66\u5e74\u300a\u4e2d\u56fd\u5b97\u6559\u53f2\u7eb2\u8981\u300b\u8bfe\u7a0b\u7684\u5b66\u4e60\uff0c\u6211\u4ece\u6700\u521d\u7684\u61f5\u61c2\u5230\u9010\u6e10\u5efa\u7acb\u8d77\u5bf9\u4e2d\u56fd\u5b97\u6559\u5386\u53f2\u7684\u7cfb\u7edf\u8ba4\u8bc6\u3002\u8001\u5e08\u4ee5\u5b97\u6559\u4e2d\u56fd\u5316\u4e3a\u4e3b\u7ebf\uff0c\u8d2f\u901a\u53e4\u4eca\uff0c\u7eb5\u6a2a\u5404\u6559\uff0c\u4f7f\u6211\u770b\u5230\u4e86\u4e2d\u56fd\u5b97\u6559\u53d1\u5c55\u7684\u6df1\u5c42\u89c4\u5f8b\u3002",

"\u8fd9\u4e9b\u89c4\u5f8b\u6027\u8ba4\u8bc6\uff0c\u5373\u5b97\u6559\u4e2d\u56fd\u5316\u662f\u5fc5\u7531\u4e4b\u8def\u3001\u653f\u6559\u5173\u7cfb\u7684\u4e1c\u65b9\u6a21\u5f0f\u3001\u4e09\u6559\u4ece\u51b2\u7a81\u5230\u878d\u5408\u3001\u539f\u751f\u578b\u5b97\u6cd5\u5b97\u6559\u7684\u4e00\u8d2f\u5b58\u7eed\u3001\u5b97\u6559\u5174\u8870\u4e0e\u793e\u4f1a\u7ecf\u6d4e\u8363\u8fb1\u4e0e\u5171\u3001\u663e\u9690\u4e8c\u6027\u4e0e\u4e09\u91cd\u7ed3\u6784\u3001\u96c5\u4fd7\u4e92\u52a8\uff0c\u4e0d\u662f\u5b64\u7acb\u7684\uff0c\u800c\u662f\u76f8\u4e92\u5173\u8054\u3001\u76f8\u4e92\u652f\u6491\u7684\u3002\u5b83\u4eec\u5171\u540c\u6784\u6210\u4e86\u7406\u89e3\u4e2d\u56fd\u5b97\u6559\u5386\u53f2\u7684\u94a5\u5319\u3002",

"\u6b63\u5982\u8bfe\u7a0b\u6240\u5f3a\u8c03\u7684\uff0c\u7814\u7a76\u4e2d\u56fd\u5b97\u6559\u53f2\u7684\u610f\u4e49\u5728\u4e8e\u5faa\u8ff9\u6eaf\u6e90\u3001\u9274\u5f80\u77e5\u6765\u3001\u4ee5\u53f2\u660e\u5fd7\u3002\u5728\u5f53\u4ee3\u4e2d\u56fd\u63a8\u8fdb\u5b97\u6559\u4e2d\u56fd\u5316\u3001\u5f15\u5bfc\u5b97\u6559\u4e0e\u793e\u4f1a\u4e3b\u4e49\u793e\u4f1a\u76f8\u9002\u5e94\u7684\u8fdb\u7a0b\u4e2d\uff0c\u8fd9\u4e9b\u5386\u53f2\u7ecf\u9a8c\u548c\u89c4\u5f8b\u6027\u8ba4\u8bc6\uff0c\u4ecd\u7136\u5177\u6709\u91cd\u8981\u7684\u73b0\u5b9e\u6307\u5bfc\u610f\u4e49\u3002\u4f5c\u4e3a\u4e00\u540d\u5b97\u6559\u754c\u53cc\u901a\u4eba\u624d\u73ed\u7684\u5b66\u751f\uff0c\u6211\u6df1\u611f\u8d23\u4efb\u91cd\u5927\uff0c\u5fc5\u5c06\u4ee5\u6b64\u8bfe\u7a0b\u6240\u5b66\u4e3a\u57fa\u7840\uff0c\u7ee7\u7eed\u5728\u5b97\u6559\u4e2d\u56fd\u5316\u7684\u9053\u8def\u4e0a\u6df1\u5165\u63a2\u7d22\u548c\u5b9e\u8df5\u3002",
]

for i, p_text in enumerate(paragraphs):
    p = doc.add_paragraph()
    is_heading = p_text.startswith(('\u4e00\u3001', '\u4e8c\u3001', '\u4e09\u3001', '\u56db\u3001', '\u4e94\u3001', '\u516d\u3001', '\u4e03\u3001', '\u7ed3\u8bed'))
    if is_heading:
        r = p.add_run(p_text)
        r.font.size = Pt(16)
        r.font.bold = True
        r.font.name = '黑体'
        p.paragraph_format.space_before = Pt(12)
        p.paragraph_format.space_after = Pt(6)
    else:
        r = p.add_run(p_text)
        r.font.size = Pt(14)
        r.font.name = '仿宋'
        p.paragraph_format.first_line_indent = Pt(28)
        p.paragraph_format.line_spacing = 1.5
        p.paragraph_format.space_after = Pt(0)

output_path = '/home/admin/.openclaw/workspace/\u4e2d\u56fd\u5b97\u6559\u53f2\u7eb2\u8981\u8bfe\u7a0b\u603b\u7ed3_v2.docx'
doc.save(output_path)
print(f"\u6587\u6863\u5df2\u4fdd\u5b58\uff1a{output_path}")

full = ''.join([p for p in paragraphs if not p.startswith(('\u4e00\u3001', '\u4e8c\u3001', '\u4e09\u3001', '\u56db\u3001', '\u4e94\u3001', '\u516d\u3001', '\u4e03\u3001', '\u7ed3\u8bed'))])
chars = len(full)
print(f"\u6b63\u6587\u5b57\u6570\uff08\u542b\u6807\u70b9\uff09\uff1a{chars}\u5b57")